// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.leo.LeoRolloutProfile;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * An unknown or negative rollout-profile value must switch LEO off at the LMDB consumer, not silently fall back to the
 * cardinality-correction default.
 */
class LmdbLeoRolloutProfileFailClosedTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P1 = VF.createIRI("urn:p1");
	private static final IRI P2 = VF.createIRI("urn:p2");

	@Test
	void negativeAndUnknownProfileValuesDisableLeoAtTheLmdbConsumer(@TempDir Path tempDir) throws Exception {
		String previousProfile = System.getProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY);
		try {
			for (String value : List.of("disabled", "false", "off", "none", "0", "safe-cardinality-corection")) {
				System.setProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, value);
				LmdbOperatorFeedbackStats stats = new LmdbOperatorFeedbackStats(
						estimatorPath(tempDir.resolve(value.replace('-', '_'))));
				Join join = join("s", "x", "o");
				assertFalse(stats.shouldExposePlanningEvidence(join),
						"profile '" + value + "' must not expose learned planning evidence");
				assertFalse(stats.shouldTrackRuntimeFeedback(join),
						"profile '" + value + "' must not even observe runtime feedback");
			}
		} finally {
			restoreProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, previousProfile);
		}
	}

	@Test
	void knownProfileValuesStillEnableTheConfiguredRung(@TempDir Path tempDir) throws Exception {
		String previousProfile = System.getProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY);
		try {
			System.setProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, "SAFE-CARDINALITY-CORRECTION");
			LmdbOperatorFeedbackStats stats = new LmdbOperatorFeedbackStats(estimatorPath(tempDir));
			Join join = join("s", "x", "o");
			assertTrue(stats.shouldTrackRuntimeFeedback(join));
			assertTrue(stats.shouldExposePlanningEvidence(join));
		} finally {
			restoreProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, previousProfile);
		}
	}

	private static Path estimatorPath(Path tempDir) throws Exception {
		Path estimatorPath = tempDir.resolve("join-estimator.rjes");
		Files.createDirectories(estimatorPath);
		Files.writeString(estimatorPath.resolve("metadata.bin"), "metadata");
		return estimatorPath;
	}

	private static Join join(String leftSubject, String sharedName, String rightObject) {
		return new Join(sp(leftSubject, P1, sharedName), sp(sharedName, P2, rightObject));
	}

	private static StatementPattern sp(String subjectName, IRI predicate, String objectName) {
		return new StatementPattern(Var.of(subjectName), Var.of("_p", predicate, true, true), Var.of(objectName));
	}

	private static void restoreProperty(String propertyName, String previous) {
		if (previous == null) {
			System.clearProperty(propertyName);
		} else {
			System.setProperty(propertyName, previous);
		}
	}
}
